local function UpsertRotationSource(data, rotation)
    data.sources = data.sources or {}
    for _, source in ipairs(data.sources) do
        if source.label == "Rotation" then
            source.updated = rotation.sourceUpdated or source.updated
            source.url = rotation.sourceURL or source.url
            return
        end
    end
    table.insert(data.sources, { label = "Rotation", updated = rotation.sourceUpdated or "unknown", url = rotation.sourceURL })
end

for specID, rotation in pairs((AGB.GuideRotationsData and AGB.GuideRotationsData.specs) or {}) do
    local meta = AGB.SpecIndex and AGB.SpecIndex[specID]
    local data = meta and AGB.Data and AGB.Data[meta.classFile] and AGB.Data[meta.classFile][specID]
    if data and rotation and rotation.sourceURL and rotation.blocks and #rotation.blocks > 0 then
        data.rotation = rotation
        UpsertRotationSource(data, rotation)
    end
end